import{_ as a,o as i,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Revealing BlueStore Corruption Bugs in Containerized Ceph Clusters","description":"","frontmatter":{"title":"Revealing BlueStore Corruption Bugs in Containerized Ceph Clusters","date":"2022-11-15T00:00:00.000Z","updated":"2022-11-16T00:00:00.000Z","tags":["Ceph","BlueStore","Data Corruption","Containerization","Storage Systems"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Revealing_BlueStore_Corruption_Bugs_in_Containerized_Ceph_Clusters.md","filePath":"posts/2022/Revealing_BlueStore_Corruption_Bugs_in_Containerized_Ceph_Clusters.md","lastUpdated":1780459816000}'),t={name:"posts/2022/Revealing_BlueStore_Corruption_Bugs_in_Containerized_Ceph_Clusters.md"};function o(n,e,s,u,h,p){return i(),l("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-cyborgs公司容器化ceph存储系统开发中的数据损坏问题及改进建议" tabindex="-1">会议主题：Cyborgs公司容器化Ceph存储系统开发中的数据损坏问题及改进建议 <a class="header-anchor" href="#会议主题-cyborgs公司容器化ceph存储系统开发中的数据损坏问题及改进建议" aria-label="Permalink to &quot;会议主题：Cyborgs公司容器化Ceph存储系统开发中的数据损坏问题及改进建议&quot;">​</a></h4><h4 id="会议参与者-cyborgs公司ceph存储系统维护团队" tabindex="-1">会议参与者：Cyborgs公司Ceph存储系统维护团队 <a class="header-anchor" href="#会议参与者-cyborgs公司ceph存储系统维护团队" aria-label="Permalink to &quot;会议参与者：Cyborgs公司Ceph存储系统维护团队&quot;">​</a></h4><h4 id="会议日期-2022年11月15日" tabindex="-1">会议日期：2022年11月15日 <a class="header-anchor" href="#会议日期-2022年11月15日" aria-label="Permalink to &quot;会议日期：2022年11月15日&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>公司及基础设施介绍</strong></p><ul><li>Cyborgs公司，一家日本软件支持团队协作提供商，正面临传统虚拟机基础设施的存储容量和性能限制。</li><li>正在开发基于Kubernetes的现代化容器化基础设施，采用Rook Ceph作为存储解决方案。</li></ul></li><li><p><strong>开发中遇到的问题</strong></p><ul><li>容器化Ceph存储系统开发过程中，发现多种数据损坏相关的bug，包括OSD创建失败和重启后数据请求损坏等问题。</li><li>这些问题主要在HDD上被检测到，可能与HDD的慢速特性有关。</li></ul></li><li><p><strong>开发策略</strong></p><ul><li>开发策略包括三次测试：通过PR提交更改，触发基于虚拟机的集成测试，测试通过后应用到预生产系统，最终部署到生产系统。</li><li>开发过程中频繁创建和重启OSD，每天进行多次集成测试，每周重启预生产环境所有节点以验证基础设施。</li></ul></li><li><p><strong>问题分析与改进建议</strong></p><ul><li>分析显示，这些问题在传统的非容器化Ceph集群中较少出现，可能与容器化环境中频繁的OSD创建和重启有关。</li><li>改进建议包括增加对OSD重启的应力测试，以及在QA过程中使用HDD以更好地检测潜在问题。</li></ul></li><li><p><strong>后续行动计划</strong></p><ul><li>继续与Ceph社区合作，验证和修复已报告的bug。</li><li>考虑在QA流程中增加更多的应力测试和使用HDD，以提高系统的稳定性和可靠性。</li><li>与Ceph社区的QA工程师联系，讨论并实施改进建议。</li><li>持续监控和更新Ceph存储系统的性能和稳定性。</li></ul></li></ol><h4 id="会议结束语" tabindex="-1">会议结束语 <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语&quot;">​</a></h4><ul><li>会议结束时，发言人感谢大家的参与，并表示希望这些信息对大家有所帮助。</li></ul><h4 id="后续行动" tabindex="-1">后续行动： <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动：&quot;">​</a></h4><ul><li>与Ceph社区的QA工程师联系，讨论并实施改进建议。</li><li>持续监控和更新Ceph存储系统的性能和稳定性。</li></ul>',11)])])}const C=a(t,[["render",o]]);export{d as __pageData,C as default};
